Section TR.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.
  Hypothesis DL : asan_driver_laws H.
  (* [comment removed for export] *)
  Variable HS : (word -> option byte) -> Prop.
  Hypothesis HSL : hs_local HS.
  Hypothesis HSI : hs_initial HS.
  Hypothesis FZ : afuzz_stmt_with H HS.

  Let rom := seg_rom bsegs.

  (* [comment removed for export] *)
  (* [comment removed for export] *)
  (* [comment removed for export] *)
  Section Call.
    Variables (sp : word) (A cap : Z) (data : list byte) (p : bptr) (s0 : as_St H) (LB : list block)
              (msF0 : machine_state) (mo0 : Model) (regs0 : bvmap 5 word) (mem0 : word -> option byte).
    Hypothesis PRE : ATRpre H sp A cap data p s0 LB msF0 mo0 regs0 mem0.

    Let cfg : Z := hdr_cfg data.
    Let N : Z := hdr_payload_len data.
    Let CP : Z := A + 2.
    Let PL : Z := A + 2 + hdr_cfg data + 4.
    (* [comment removed for export] *)
    Let ds : list byte := firstn (Z.to_nat N) (skipn (Z.to_nat (6 + cfg)) data).
    Let calls : nat := hdr_calls data.

    Let HCLO : aceil + ATR_STACK + 4096 <= bv_unsigned sp.
    Proof. exact (atr_splo _ _ _ _ _ _ _ _ _ _ _ _ PRE). Qed.
    Let SPlo : 0x7fff7f811000 <= bv_unsigned sp.
    Proof. pose proof HCLO as X. acb. unfold ATR_STACK in X. lia. Qed.
    Let SPhi : bv_unsigned sp <= 0x7fffffffff80.
    Proof. pose proof (atr_sphi _ _ _ _ _ _ _ _ _ _ _ _ PRE). lia. Qed.
    Let SP16 : bv_unsigned sp mod 16 = 0.
    Proof. exact (atr_sp16 _ _ _ _ _ _ _ _ _ _ _ _ PRE). Qed.
    Let Hcfg : 0 <= cfg < 32768. Proof. exact (hdr_cfg_range data). Qed.
    Let HN : 0 <= N < 2 ^ 26.
    Proof. pose proof (atr_len6 _ _ _ _ _ _ _ _ _ _ _ _ PRE). pose proof (atr_lenhi _ _ _ _ _ _ _ _ _ _ _ _ PRE). unfold MAX_INPUT in *. subst N. unfold hdr_payload_len. subst cfg. lia. Qed.
    Let Hds : length ds = Z.to_nat N.
    Proof.
      pose proof (atr_len6 _ _ _ _ _ _ _ _ _ _ _ _ PRE). subst ds N cfg. unfold hdr_payload_len in *.
      rewrite length_firstn, length_skipn. lia.
    Qed.
    Let Hcalls : (1 <= calls <= 4)%nat. Proof. exact (hdr_calls_range data). Qed.

    (* [comment removed for export] *)
    Definition atr_region (r : word * Z) : Prop :=
      (bv_unsigned sp - ATR_STACK <= bv_unsigned (fst r) /\ bv_unsigned (fst r) + snd r <= bv_unsigned sp /\ 0 <= snd r)
      \/ (0x123fe0 <= bv_unsigned (fst r) /\ bv_unsigned (fst r) + snd r <= 0x1240c8 /\ 0 <= snd r)
      \/ (0x681f00 <= bv_unsigned (fst r) /\ bv_unsigned (fst r) + snd r <= 0x681f08 /\ 0 <= snd r)
      \/ (bv_unsigned (fst r) = 0x65fe14 /\ snd r = 1).

    (* [comment removed for export] *)
    Definition atr_cells : list (Z * nat * Z) :=
      adrv_common ++ [(0x681848, 4%nat, 2); (0x681868, 8%nat, 0x103594); (0x681968, 8%nat, 0x0a43c4)]%Z.

    Record atinv (m : word -> option byte) : Prop := ATI {
      ti_inv   : mem_inv bsegs m;
      ti_stk   : stk bsegs m (bv_unsigned sp - ATR_STACK) (bv_unsigned sp);
      ti_ac    : ACONST m;
      ti_relro : arelro_none m;
      ti_glb   : aglb_none m;
      ti_cells : cells_ok m atr_cells;
      ti_latch : rdn RSEGS m (Z_to_bv 64 0x65fe10) 1 = Some [Z_to_bv 8 1];     (* [comment removed for export] *)
      ti_axtab : rw_cells bsegs m A_ATEXIT (aatexit_tab true);                (* [comment removed for export] *)
      ti_prist : AXFuzz_stmt.pristine m AXDATA_LO AXDATA_HI;                 (* [comment removed for export] *)
      ti_tid   : exists t, atid_cell m t;
      ti_errno : exists e, rw_cells bsegs m AERRNO [C4 e];
      ti_can   : exists can, acanary m can;
      ti_rfs   : as_RFS H [] m;
      ti_sh0   : exists shi, stack0 m (bv_unsigned sp - ATR_STACK) shi /\ bv_unsigned sp <= shi;
      ti_above : forall a : word, bv_unsigned sp <= bv_unsigned a -> m a = mem0 a;
      ti_aux   : exists B', as_rauxv_ok H m B' /\ bv_unsigned sp + 128 <= B' < 2 ^ 64;
      ti_addr  : addressable m A cap;
      ti_data  : rdn RSEGS m (Z_to_bv 64 A) (length data) = Some data;
      ti_cb    : exists junk, rw_cells bsegs m A [CB (Z.to_nat cap) junk] }.

    Lemma adrv_cells_wf : forallb cell_wf_b atr_cells = true. Proof. vm_compute. reflexivity. Qed.
    Lemma adrv_cells_range :
      Forall (fun c : Z * nat * Z => match c with (a, w, _) =>
        (0x121460 <= a /\ a + Z.of_nat w <= 0x123f84) \/ (a = 0x12a150 /\ w = 1%nat) \/ (0x681840 <= a /\ a + Z.of_nat w <= 0x681a84) \/ (a = 0x681ee8 /\ w = 8%nat) end) atr_cells.
