    Lemma fuzz_cost_nonneg : forall n, 0 <= n -> 0 <= afuzz_cost H n.
    Proof.
      intros n Hn. exact (afuzz_cost_nonneg H HH n Hn).   (* [comment removed for export] *)
    Qed.

    (* [comment removed for export] *)
    Definition xfar (XS : list (Z * Z)) : Prop := Forall (fun iv : Z * Z => AIMG_TOP <= fst iv /\ snd iv <= aceil) XS.

