    Lemma scratch_far : forall m XS, as_RFS H [] m -> Forall (fs_scratch H []) XS -> xfar XS.
    Proof. intros m XS RFS F. eapply Forall_impl; [| exact F]. intros iv Hiv. eapply scratch_iv; [exact RFS | exact Hiv]. Qed.

