    Definition aatexit_fix_cells : list (Z * nat * Z) :=
      [(0x681840, 1%nat, 0); (0x681844, 4%nat, 0); (0x681848, 4%nat, 2); (0x681850, 8%nat, 0x681858); (0x681858, 8%nat, 0);
