    (* [comment removed for export] *)
    Let W02 : list (Z * Z) := [(bv_unsigned sp - ATR_STACK, bv_unsigned sp); (0x65fe10, 0x65fe11); (A_ATEXIT, A_ATEXIT + 544)]%Z.

    Lemma entry_munch : forall m1 m2,
      frame_mod mem0 m1 (regTb_w sp) ->
      munch [(bv_unsigned sp - ATR_STACK, bv_unsigned sp - 80); (A_ATEXIT, A_ATEXIT + 544)]%Z m1 m2 -> wmono bsegs m1 m2 ->
      munch W02 mem0 m2 /\ wmono bsegs mem0 m2.
    Proof.
      intros m1 m2 FM MU WM. pose proof SPlo. split.
      - eapply munch_trans; [| eapply munch_weaken; [| exact MU]].
        + eapply munch_weaken; [| apply frame_mod_munch; exact FM].
          intros x Hx. unfold W02, A_ATEXIT, ATR_STACK in Hx. unfold regTb_w. cbn [ivls map fst snd outside] in Hx |- *.
          rewrite !u_small by lia. lia.
        + intros x Hx. unfold W02, ATR_STACK in Hx |- *. cbn [outside] in Hx |- *. lia.
